def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    priorities = np.full_like(bins, -np.inf)
    valid_mask = bins >= item
    if not np.any(valid_mask):
        return priorities

    target_fill_ratio = 0.85
    target_remaining = bins * (1 - target_fill_ratio)
    deviation = np.abs(remaining - target_remaining)

    underfit_mask = valid_mask & (remaining >= 0)
    overfit_mask = valid_mask & (remaining < 0)

    if np.any(underfit_mask):
        max_dev = np.max(deviation[underfit_mask])
        if max_dev > 0:
            priorities[underfit_mask] = 2 - (deviation[underfit_mask] / max_dev)
        else:
            priorities[underfit_mask] = 2

    if np.any(overfit_mask):
        max_dev = np.max(deviation[overfit_mask])
        if max_dev > 0:
            priorities[overfit_mask] = 1 - (deviation[overfit_mask] / max_dev)
        else:
            priorities[overfit_mask] = 1

    return priorities
